; Huffman-compressed text group(s): $56
; Text $0AC0: This is the Final Refuge.I've been waiting for you.'<44>
; Text $0AC1: Necrosaro has barriers around his palace.His evolution is in progress.'<4F>Unless you break the four barriers,some mysterious force will prevent your progress.'<4F>Break the barriers first!'<44>
; Text $0AC2: The barriers are gone!'<4F>Don't forget.If you use the Baron's Horn before the final battle,you can call the wagon.'<44>
; Text $0AC3: Best of luck to <49> and the companions!
; Text $0AC4: <4E><44>'Do you wish to have your progress recorded on the Imperial Scrolls of Honor?'
; Text $0AC5: I certainly recorded it.'<44>
; Text $0AC6: Go now.
; Text $0AC7: I commend you for coming this far!'<4F>I'll give you a reward.Check the floor behind you.
; Text $0AC8: He,He,He! You could have ended your life in peace if you hadn't struggled.'<4F>You fools!
; Text $0AC9: It's my duty to guard these barriers.'<4F>I won't let you break them.Come fight if you dare!
; Text $0ACA: Are you the ones who threaten Necrosaro's evolution?'<4F>I'll send you to oblivion!
; Text $0ACB: I'm impressed you reached here,<49>.'<4F>But it's too late.'<4F>Soon Necrosaro shall awake as our ruler.'<4F>Only hatred shall remain in his soul.'<4F>I shall demolish you!'<44>
; Text $0ACC: I'm the one who ordered the abduction of Rosa.Ha,Ha,Ha!
; Text $0ACD: Oh,<49>! You're the true Hero!
; Text $0ACE: I'll be busy! I have to add this latest event to the history.
; Text $0ACF: Upon reflection,I think Necrosaro was unfortunate too.
; Text $0AD0: Twirl...Twirl....Peace has returned to the world!
; Text $0AD1: <4E>Lita:'Let's be friends from now on.'
; Text $0AD2: Hmm...not all humans are bad.Don't you think so,Lita?'<44>Lita:'I agree,sister.'
; Text $0AD3: Everything turned out fine!
; Text $0AD4: Thank you very much.I won't have to watch people suffer anymore.
; Text $0AD5: Gugoon,Gugoon.
; Text $0AD6: You defeated the second Ruler of Evil? Incredible!
; Text $0AD7: <4E>Doran:'Gogogoon!'
; Text $0AD8: <4E>Lucia:'<50> and others! I'll always be proud that I traveled with you!'
; Text $0AD9: Well done! I think better of you now.
; Text $0ADA: Look at the earth people's joyous faces.
; Text $0ADB: <49>,even though you don't have a father or a mother,you have such fine friends....'<4F>Everyone,please be true friends to <49> forever.Sob...Sob...
; Text $0ADC: We shouldn't underestimate human courage.
; Text $0ADD: Your words will be recorded here and will be handed down to future generations.
; Text $0ADE: Very Impressive! Very! Why don't you stay and live with us?
; Text $0ADF: You lack wings,yet you defeated the Ruler of Evil! Hard to believe!
Bank1B_TextGroup_56:
