; Huffman-compressed text group(s): $57
; Text $0AE0: You're leaving,aren't you? Take care....
; Text $0AE1: Even if the world ends today,our love shall remain unchanged forever.What a line,huh?
; Text $0AE2: Your balloon and wagon are outside.
; Text $0AE3:
; Text $0AE4: rrrrp not wake him.Do not go near him.'<4F>...says the book.'<4F>Later it was found that Esturk's Secret of Evolution had been imperfect.'<4F>It didn't incorporate the Golden Bracelet,an amplifier of the evil undulation.
; Text $0AE5: Here is our ruler,Master Dragon!
; Text $0AE6: I see...<50> is the Hero,a Zenithian and human descendant.'<44>
; Text $0AE7: It appears that Master Dragon has always cared about <50>.
; Text $0AE8: Many years ago,a girl went down to earth and fell in love with a young woodsman.'<4F>They soon had a child.'<4F>Not long after,the woodsman was struck by a bolt of lightning and died.The girl was taken back to Zenithia.'<4F>She's never forgotten the child she left behind on earth.'<4F>If she saw <50>,she'd cry with joy.Sob...Sob...
; Text $0AE9: What's happening?'<4F>Ominous clouds are covering the earth.
; Text $0AEA: What am I doing? I'm growing world trees.'<4F>I'll give you the Dew of World Tree.'<44>
; Text $0AEB: <4E><49> obtained the Dew of World Tree!
; Text $0AEC: I meant it,but you can't carry any more things.Come back again.
; Text $0AED: Oh,you want the Dew of World Tree?'<44>
; Text $0AEE: Don't be so greedy.When it's gone,I'll give you more.
; Text $0AEF: Hmm...don't tell anyone,OK?'<44>
; Text $0AF0: Gwoon,Gwoon.
; Text $0AF1: Grururu...
; Text $0AF2: It's reported that Necrosaro built barriers to protect the Secret of Evolution.'<4F>To stop him,the barriers must be broken.'<4F>Good luck,<50>!
; Text $0AF3: <4E>Lucia:'It's you! Thanks to you,I can take care of these children.'<44>Lucia:'I want to show my appreciation....'<44>
; Text $0AF4: eeThis is the Final Refuge.I've been waiting for you.'<44>
; Text $0AF5: Necrosaro has barriers around his palace.His evolution is in progress.'<4F>Unless you break the four barriers,some mysterious force will prevent your progress.'<4F>Break the barriers first!'<44>
; Text $0AF6: The barriers are gone!'<4F>Don't forget.If you use the Baron's Horn before the final battle,you can call the wagon.'<44>
; Text $0AF7: Best of luck to <49> and the companions!
; Text $0AF8: <4E><44>'Do you wish to have your progress recorded on the Imperial Scrolls of Honor?'
; Text $0AF9: I certainly recorded it.'<44>
; Text $0AFA: Go now.
; Text $0AFB: I commend you for coming this far!'<4F>I'll give you a reward.Check the floor behind you.
; Text $0AFC: He,He,He! You could have ended your life in peace if you hadn't struggled.'<4F>You fools!
; Text $0AFD: It's my duty to guard these barriers.'<4F>I won't let you break them.Come fight if you dare!
; Text $0AFE: Are you the ones who threaten Necrosaro's evolution?'<4F>I'll send you to oblivion!
; Text $0AFF: I'm impressed you reached here,<49>.'<4F>But it's too late.'<4F>Soon Necrosaro shall awake as our ruler.'<4F>Only hatred shall remain in his soul.'<4F>I shall demolish you!'<44>
